6	/// Classification of a `crate::Error` for routing and display decisions.
7	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
8	#[non_exhaustive]
9	pub enum ErrorClass {
10	    /// The caller provided invalid input. Do not retry.
11	    User,
12	    /// A downstream or infrastructure failure that is not the caller's direct
13	    /// error and is not expected to self-resolve without intervention. Note:
14	    /// `RateLimited` falls here when `retryable: false` — the caller may have
15	    /// contributed to the rate-limit condition, but at classification time the
16	    /// error is not self-resolving. michi does not recommend automatic retry
17	    /// for `Internal` errors.
18	    Internal,
19	    /// A failure that trying the same call again is expected to fix, without repeating an effect: the request was
20	    /// not processed (rate limited, unavailable), or the caller marked the error retryable because the operation is
21	    /// idempotent.
22	    Transient,
23	    /// A timeout: no answer came back, so the operation may or may not have taken effect. Not the caller's fault and
24	    /// not an internal error: verify whether it completed before retrying, unless the operation is idempotent, in
25	    /// which case the caller marks it retryable and it is [`ErrorClass::Transient`].
26	    Ambiguous,
27	}
28	
29	/// The hint a fresh `Timeout` [`DomainError`] carries until it is marked retryable.
30	pub const MAY_HAVE_TAKEN_EFFECT_HINT: &str =
31	    "the operation may have taken effect; verify whether it completed before retrying, unless it is idempotent";
32	
33	/// Wraps a value so its inner content is omitted from `Debug` and `Display`.
34	///
35	/// That is all it does: the field is public, and none of michi's renderers takes a `Sensitive`. Text passed to a hint,
36	/// an error message or a cause is rendered as given, so keep secrets out of those strings in the first place.
37	#[derive(Clone)]
38	pub struct Sensitive<T>(pub T);
39	
40	impl<T> std::fmt::Debug for Sensitive<T> {
41	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
42	        f.write_str("<redacted>")
43	    }
44	}
45	
46	impl<T> std::fmt::Display for Sensitive<T> {
47	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
48	        f.write_str("<redacted>")
49	    }
50	}
