52	/// The specific kind of domain error.
53	///
54	/// Rendered output uses the snake_case [`ErrorCode::label`]; with the `schemars` feature its schema is the enum of
55	/// those labels, matching the `error` field of [`DomainError::render_json`].
56	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
57	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
58	#[cfg_attr(feature = "schemars", schemars(rename_all = "snake_case"))]
59	#[non_exhaustive]
60	pub enum ErrorCode {
61	    /// Bad parameters.
62	    InvalidInput,
63	    /// Resource absent.
64	    NotFound,
65	    /// Auth failure.
66	    Unauthorized,
67	    /// Permission denied.
68	    Forbidden,
69	    /// Resource state mismatch.
70	    Conflict,
71	    /// Rate limited (HTTP 429).
72	    RateLimited,
73	    /// Service unavailable (HTTP 503).
74	    Unavailable,
75	    /// Request timed out.
76	    Timeout,
77	    /// Downstream/external failure.
78	    ExternalFailure,
79	}
80	
81	impl ErrorCode {
82	    /// The snake_case label used in rendered output.
83	    #[must_use]
84	    pub fn label(&self) -> &'static str {
85	        match self {
86	            Self::InvalidInput => "invalid_input",
87	            Self::NotFound => "not_found",
88	            Self::Unauthorized => "unauthorized",
89	            Self::Forbidden => "forbidden",
90	            Self::Conflict => "conflict",
91	            Self::RateLimited => "rate_limited",
92	            Self::Unavailable => "unavailable",
93	            Self::Timeout => "timeout",
94	            Self::ExternalFailure => "external_failure",
95	        }
96	    }
97	
98	    /// Every code, in declaration order. `FromStr` searches this list, so a label is parsed by the same table that
99	    /// [`label`](Self::label) writes; a unit test names every variant without a wildcard, so a new one fails to
100	    /// compile there until it is listed here.
101	    pub const ALL: [Self; 9] = [
102	        Self::InvalidInput,
103	        Self::NotFound,
104	        Self::Unauthorized,
105	        Self::Forbidden,
106	        Self::Conflict,
107	        Self::RateLimited,
108	        Self::Unavailable,
109	        Self::Timeout,
110	        Self::ExternalFailure,
111	    ];
112	
113	    /// Whether a fresh [`DomainError`] with this code is retryable: `RateLimited` and `Unavailable` only, which mean
114	    /// the request was not processed. `Timeout` and `ExternalFailure` are not: the request may have taken effect
115	    /// (RFC 9110 §15.6), so retrying is safe only for an idempotent operation, and the caller says so with
116	    /// [`DomainError::retryable`].
117	    #[must_use]
118	    pub fn is_retryable_by_default(&self) -> bool {
119	        matches!(self, Self::RateLimited | Self::Unavailable)
120	    }
121	
122	    /// Whether a failure with this code leaves it unknown whether the request was applied: `Timeout`, where no
123	    /// answer came back. `ExternalFailure` is too broad to say (a failed local walk, a server error), so the caller
124	    /// adds a hint when it knows; `RateLimited` and `Unavailable` mean the request was not processed.
125	    #[must_use]
126	    pub fn may_have_taken_effect(&self) -> bool {
127	        matches!(self, Self::Timeout)
128	    }
129	
130	    /// The default [`ErrorClass`] for this code, independent of `DomainError.retryable`.
131	    ///
132	    /// `Timeout` returns `Ambiguous` (the operation may have taken effect); `RateLimited`, `Unavailable` and
133	    /// `ExternalFailure` return `Internal`; caller-fault codes return `User`. Used by [`Error::class()`] when the error
134	    /// is not marked retryable.
135	    #[must_use]
136	    pub fn default_class(&self) -> ErrorClass {
137	        match self {
138	            Self::InvalidInput | Self::NotFound | Self::Unauthorized | Self::Forbidden | Self::Conflict => {
139	                ErrorClass::User
140	            }
141	            Self::RateLimited | Self::Unavailable | Self::ExternalFailure => ErrorClass::Internal,
142	            Self::Timeout => ErrorClass::Ambiguous,
143	        }
144	    }
145	}
146	
147	/// A string that is not an [`ErrorCode`] label.
148	#[derive(Debug, Clone, PartialEq, Eq)]
149	pub struct UnknownErrorCode(pub String);
150	
151	impl std::fmt::Display for UnknownErrorCode {
152	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
153	        write!(f, "unknown error code {:?}; expected one of: ", self.0)?;
154	        for (i, code) in ErrorCode::ALL.iter().enumerate() {
155	            f.write_str(if i == 0 { "" } else { ", " })?;
156	            f.write_str(code.label())?;
157	        }
158	        Ok(())
159	    }
160	}
161	
162	impl std::error::Error for UnknownErrorCode {}
163	
164	impl std::str::FromStr for ErrorCode {
165	    type Err = UnknownErrorCode;
166	
167	    /// The code whose [`label`](ErrorCode::label) is `s`.
168	    fn from_str(s: &str) -> Result<Self, Self::Err> {
169	        Self::ALL.into_iter().find(|code| code.label() == s).ok_or_else(|| UnknownErrorCode(s.to_string()))
170	    }
171	}
