173	/// A domain-level error.
174	///
175	/// `causes` say why it happened (diagnosis); `hints` say what to do next (guidance). They are separate fields, and
176	/// render as separate keys, so an agent can tell them apart. [`DomainError::from_error_with_causes`] fills `message` and `causes`
177	/// from a `std::error::Error` and its `source()` chain.
178	///
179	/// With the `serde` feature it serializes to exactly the JSON of [`DomainError::render_json`]
180	/// (`{isError, error, message, causes, retryable, hints, recovery}`), and with `schemars` its schema describes that
181	/// form, so it can be used as an MCP `outputSchema`. `retry_after` is not part of that form.
182	#[derive(Debug, Clone)]
183	#[cfg_attr(feature = "serde", derive(serde::Serialize))]
184	#[cfg_attr(feature = "serde", serde(into = "DomainErrorWire"))]
185	#[non_exhaustive]
186	pub struct DomainError {
187	    /// The error classification.
188	    pub code: ErrorCode,
189	    /// Human-readable message.
190	    pub message: String,
191	    /// Why it happened, outermost first: one entry per underlying cause, rendered as `causes[N]: …` after the
192	    /// message. Diagnosis only; what the agent should do next goes in `hints`.
193	    pub causes: Vec<String>,
194	    /// Contextual hints, rendered as a trailing `help[N]:` block.
195	    pub hints: Vec<Hint>,
196	    /// Optional structured recovery hint.
197	    pub recovery: Option<RecoveryHint>,
198	    /// Whether calling again is expected to help without repeating an effect. Defaults to `true` only for
199	    /// `RateLimited` and `Unavailable` (the request was not processed); set it for a `Timeout` or `ExternalFailure`
200	    /// only when the operation is idempotent, since the failed attempt may have taken effect.
201	    pub retryable: bool,
202	    /// Parsed `Retry-After` delay, if known.
203	    pub retry_after: Option<Duration>,
204	}
205	
206	impl DomainError {
207	    /// Create a domain error. The message is tool-author text, never data: michi renders it as the error's own
208	    /// voice, and a value copied from a file, web page or user field can carry instructions. See the trust model in
209	    /// `docs/spec/02-toon-format.md`.
210	    pub fn new(code: ErrorCode, message: impl Into<String>) -> Self {
211	        let mut err = Self {
212	            retryable: code.is_retryable_by_default(),
213	            code,
214	            message: message.into(),
215	            causes: Vec::new(),
216	            hints: Vec::new(),
217	            recovery: None,
218	            retry_after: None,
219	        };
220	        err.sync_effect_hint();
221	        err
222	    }
223	
224	    /// Keeps [`MAY_HAVE_TAKEN_EFFECT_HINT`] present exactly while the error's code may have taken effect and it is not
225	    /// marked retryable.
226	    fn sync_effect_hint(&mut self) {
227	        let wanted = self.code.may_have_taken_effect() && !self.retryable;
228	        let present = self.hints.iter().any(|h| h.as_str() == MAY_HAVE_TAKEN_EFFECT_HINT);
229	        if wanted && !present {
230	            self.hints.push(Hint::new(MAY_HAVE_TAKEN_EFFECT_HINT));
231	        } else if !wanted && present {
232	            self.hints.retain(|h| h.as_str() != MAY_HAVE_TAKEN_EFFECT_HINT);
233	        }
234	    }
235	
236	    /// Build a domain error from an existing error, keeping only its own `Display` as `message`.
237	    ///
238	    /// The `source()` chain is **not** copied: underlying errors often carry URLs with tokens, file paths and other
239	    /// internals that should not reach an agent. Use [`DomainError::from_error_with_causes`] to opt in to the chain.
240	    /// The top-level `Display` is still agent-visible, so make sure it is safe to show; if it is not, build the
241	    /// error with [`DomainError::new`] and a message you wrote. The message is tool-author text, never data. As a
242	    /// safety net the text goes through [`crate::redact::redact_common_shapes`]: URL userinfo, the values of
243	    /// `token=`/`api_key=`/`password=`-style pairs (a `reqwest` error puts the whole URL, query included, in its
244	    /// top-level `Display`) and a few token prefixes become `[REDACTED]`. That is best effort, not a guarantee: see
245	    /// that function for what it misses.
246	    ///
247	    /// ```
248	    /// use michi_core::{DomainError, ErrorCode};
249	    ///
250	    /// #[derive(Debug, thiserror::Error)]
251	    /// #[error("sync failed")]
252	    /// struct Sync(#[source] std::io::Error);
253	    ///
254	    /// let io = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "/home/ci/.netrc: permission denied");
255	    /// let e = DomainError::from_error(ErrorCode::ExternalFailure, &Sync(io));
256	    /// assert_eq!(e.message, "sync failed");
257	    /// assert!(e.causes.is_empty());
258	    /// ```
259	    pub fn from_error(code: ErrorCode, err: &(dyn std::error::Error + 'static)) -> Self {
260	        Self::new(code, crate::redact::redact_common_shapes(&err.to_string()))
261	    }
262	
263	    /// Like [`DomainError::from_error`], and also copies the `source()` chain into `causes`. Opt-in: every link's
264	    /// `Display` becomes agent-visible text, so use it only when the whole chain is safe to show (no URLs with
265	    /// tokens, no paths or internals you would not print to an end user). The same redaction is applied to every link, as in
266	    /// [`DomainError::from_error`].
267	    ///
268	    /// Each `source()` link, outermost first, adds its `Display` as one entry of `causes` (never a hint: causes are
269	    /// diagnosis, hints are guidance). A link whose text is already contained in the last text kept (the message, or
270	    /// the previous cause kept) is skipped, because `thiserror` messages often embed their source
271	    /// (`#[error("walk failed: {0}")]`) and would otherwise repeat it. Line breaks stay inside their entry; the
272	    /// renderers escape them. The walk stops after 128 links, so a cyclic `source()` cannot loop.
273	    ///
274	    /// The chain is kept as text only: no source error is stored, so [`std::error::Error::source`] on the result is
275	    /// still `None`, and the result stays `Clone`, `Send` and `Sync`. Prefix the message yourself if you want one
276	    /// (`e.message = format!("walk: {}", e.message)`).
277	    ///
278	    /// ```
279	    /// use michi_core::{DomainError, ErrorCode};
280	    ///
281	    /// #[derive(Debug, thiserror::Error)]
282	    /// #[error("walk failed: {0}")]
283	    /// struct Walk(#[source] std::io::Error);
284	    ///
285	    /// let io = std::io::Error::new(std::io::ErrorKind::PermissionDenied, "permission denied");
286	    /// let e = DomainError::from_error_with_causes(ErrorCode::ExternalFailure, &Walk(io));
287	    /// assert_eq!(e.message, "walk failed: permission denied");
288	    /// assert!(e.causes.is_empty(), "the message already holds the only cause");
289	    /// ```
290	    pub fn from_error_with_causes(code: ErrorCode, err: &(dyn std::error::Error + 'static)) -> Self {
291	        let mut out = Self::from_error(code, err);
292	        let mut link = err.source();
293	        for _ in 0..MAX_CAUSE_LINKS {
294	            let Some(e) = link else { break };
295	            let text = crate::redact::redact_common_shapes(&e.to_string());
296	            let previous = out.causes.last().unwrap_or(&out.message);
297	            if !previous.contains(text.as_str()) {
298	                out.causes.push(text);
299	            }
300	            link = e.source();
301	        }
302	        out
303	    }
304	
305	    /// Append one cause (why the error happened), rendered after the message as `causes[N]: …`. Tool-author text,
306	    /// never data, and nothing you would not show an end user (no tokens, internal paths).
307	    #[must_use]
308	    pub fn cause(mut self, cause: impl Into<String>) -> Self {
309	        self.causes.push(cause.into());
310	        self
311	    }
312	
313	    /// Append a contextual hint. Tool-author text, never data.
314	    #[must_use]
315	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
316	        self.hints.push(Hint::new(hint));
317	        self
318	    }
319	
320	    /// Attach a structured recovery hint.
321	    #[must_use]
322	    pub fn recovery(mut self, r: RecoveryHint) -> Self {
323	        self.recovery = Some(r);
324	        self
325	    }
326	
327	    /// Override the default retryability for this error instance. Pass `true` for a `Timeout` or `ExternalFailure`
328	    /// only when repeating the operation is safe (it is idempotent, or known not to have taken effect).
329	    #[must_use]
330	    pub fn retryable(mut self, retryable: bool) -> Self {
331	        self.retryable = retryable;
332	        self.sync_effect_hint();
333	        self
334	    }
335	
336	    /// Attach a `Retry-After` delay.
337	    #[must_use]
338	    pub fn retry_after(mut self, d: Duration) -> Self {
339	        self.retry_after = Some(d);
340	        self
341	    }
342	
343	    /// The process exit code to use when this error is fatal. Always `1`.
344	    #[must_use]
345	    pub fn exit_code(&self) -> i32 {
346	        1
347	    }
348	
349	    /// Render as a TOON 4.4 root object, with no trailing newline: `error: <code label>`, `message: …` (quoted per
350	    /// §7.2), the inline `causes[N]: …` array when there are causes, `exit_code: 1`, then the inline `help[N]: …`
351	    /// array and the `recovery[1]{tool,params,reason}:` table when present.
352	    #[must_use]
353	    pub fn render(&self) -> String {
354	        let causes_est: usize = self.causes.iter().map(|c| c.len() + 3).sum();
355	        let mut out = String::with_capacity(96 + self.message.len() + causes_est + self.hints.len() * 50);
356	        push_error_fields(&mut out, self.code.label(), &self.message, &self.causes);
357	        crate::hints::append_hints(&mut out, &self.hints);
358	        if let Some(r) = &self.recovery {
359	            crate::recovery::append_recovery(&mut out, std::slice::from_ref(r));
360	        }
361	        out
362	    }
363	
364	    /// Render formatted for GitHub Actions workflow annotations (`::error title=code::message`).
365	    ///
366	    /// The message is encoded as GitHub workflow command data: `%` becomes `%25` first, then CR and LF become `%0D`
367	    /// and `%0A`, so the annotation stays on one line and a literal `%0A` in the message cannot decode to a line
368	    /// break. The `title` property is encoded the same way plus `:` → `%3A` and `,` → `%2C`.
369	    #[must_use]
370	    pub fn render_github_annotation(&self) -> String {
371	        format!(
372	            "::error title={}::{}",
373	            escape_annotation_property(self.code.label()),
374	            escape_annotation_data(&self.message)
375	        )
376	    }
377	
378	    /// Render as a compact JSON object, the `structured_content` companion of [`DomainError::render`].
379	    ///
380	    /// Keys: `isError`, `error`, `message`, `causes`, `retryable`, `hints`, `recovery`. `causes` and `hints` are
381	    /// always present, as `[]` when empty; `recovery` is the hint object, or `null`. The shape differs from
382	    /// `AgentResponse`'s JSON (`{body, hints, recovery, isError}`, with `recovery` an array); only `isError` and
383	    /// `hints` mean the same in both.
384	    #[must_use]
385	    pub fn render_json(&self) -> String {
386	        let hints_est: usize = self.hints.iter().map(|h| h.as_str().len() + 4).sum();
387	        let causes_est: usize = self.causes.iter().map(|c| c.len() + 4).sum();
388	        let recovery_est: usize = self.recovery.as_ref().map_or(0, |r| {
389	            50 + r.tool.len()
390	                + r.params.iter().map(|_| 20usize).sum::<usize>()
391	                + r.reason.as_ref().map_or(0, |s| s.len() + 12)
392	        });
393	        let mut out = String::with_capacity(140 + self.message.len() + causes_est + hints_est + recovery_est);
394	        out.push_str("{\"isError\":true,\"error\":");
395	        crate::json::push_str(&mut out, self.code.label());
396	        out.push_str(",\"message\":");
397	        crate::json::push_str(&mut out, &self.message);
398	        out.push_str(",\"causes\":");
399	        crate::json::push_str_array(&mut out, self.causes.iter().map(String::as_str));
400	        out.push_str(",\"retryable\":");
401	        crate::json::push_bool(&mut out, self.retryable);
402	        out.push_str(",\"hints\":");
403	        crate::json::push_str_array(&mut out, self.hints.iter().map(Hint::as_str));
404	        out.push_str(",\"recovery\":");
405	        match &self.recovery {
406	            None => out.push_str("null"),
407	            Some(r) => crate::json::push_recovery(&mut out, r),
408	        }
409	        out.push('}');
410	        out
411	    }
412	
413	    /// Build an MCP [`CallToolResult`](crate::mcp::CallToolResult) representing this error.
414	    ///
415	    /// Sets `is_error: true`. Text content uses [`DomainError::render()`];
416	    /// `structured_content` uses [`DomainError::render_json()`].
417	    ///
418	    /// **Canonical path:** call this directly when you hold a `DomainError`.
419	    /// Do not wrap in `AgentResponse::as_error()` — that loses typed fields.
420	    #[must_use]
421	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
422	        crate::mcp::CallToolResult {
423	            content: vec![crate::mcp::ContentBlock {
424	                text: self.render(),
425	                audience: vec![crate::audience::Audience::Assistant],
426	            }],
427	            is_error: true,
428	            structured_content: self.render_json(),
429	        }
430	    }
431	}
432	
433	/// The wire form of [`DomainError`]: the object `render_json()` writes.
434	#[cfg(feature = "serde")]
435	#[derive(serde::Serialize)]
436	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
437	#[cfg_attr(feature = "schemars", schemars(rename = "DomainError"))]
438	#[serde(rename_all = "camelCase")]
439	struct DomainErrorWire {
440	    /// Always `true`.
441	    #[cfg_attr(feature = "schemars", schemars(schema_with = "const_true_schema"))]
442	    is_error: bool,
443	    /// The snake_case error code label.
444	    #[cfg_attr(feature = "schemars", schemars(with = "ErrorCode"))]
445	    error: &'static str,
446	    /// Human-readable message.
447	    message: String,
448	    /// Why it happened, outermost first; `[]` when unknown.
449	    causes: Vec<String>,
450	    /// Whether calling again is expected to help without repeating an effect.
451	    retryable: bool,
452	    /// Contextual hints.
453	    hints: Vec<String>,
454	    /// The structured recovery hint, or `null`.
455	    recovery: Option<RecoveryHint>,
456	}
457	
458	#[cfg(feature = "schemars")]
459	fn const_true_schema(_: &mut schemars::SchemaGenerator) -> schemars::Schema {
460	    schemars::json_schema!({ "type": "boolean", "const": true })
461	}
462	
463	#[cfg(feature = "serde")]
464	impl From<DomainError> for DomainErrorWire {
465	    fn from(e: DomainError) -> Self {
466	        Self {
467	            is_error: true,
468	            error: e.code.label(),
469	            message: e.message,
470	            causes: e.causes,
471	            retryable: e.retryable,
472	            hints: e.hints.iter().map(|h| h.as_str().to_string()).collect(),
473	            recovery: e.recovery,
474	        }
475	    }
476	}
