478	// The schema describes the render_json()/serde wire form above, not the Rust field layout.
479	#[cfg(feature = "schemars")]
480	#[cfg_attr(docsrs, doc(cfg(feature = "schemars")))]
481	impl schemars::JsonSchema for DomainError {
482	    fn schema_name() -> std::borrow::Cow<'static, str> {
483	        DomainErrorWire::schema_name()
484	    }
485	
486	    fn schema_id() -> std::borrow::Cow<'static, str> {
487	        DomainErrorWire::schema_id()
488	    }
489	
490	    fn json_schema(generator: &mut schemars::SchemaGenerator) -> schemars::Schema {
491	        DomainErrorWire::json_schema(generator)
492	    }
493	}
494	
495	impl std::fmt::Display for DomainError {
496	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
497	        write!(f, "{}: {}", self.code.label(), self.message)
498	    }
499	}
500	
501	/// `source()` is always `None`: [`DomainError::from_error_with_causes`] keeps a chain as text in `causes`, not as a stored error.
502	impl std::error::Error for DomainError {}
503	
504	/// The most `source()` links [`DomainError::from_error_with_causes`] walks, so a cyclic chain cannot loop forever.
505	const MAX_CAUSE_LINKS: usize = 128;
506	
507	/// Encode GitHub workflow command data (the message): `%` first, so an encoded sequence in the input stays literal,
508	/// then CR and LF.
509	fn escape_annotation_data(s: &str) -> String {
510	    let mut out = String::with_capacity(s.len() + 8);
511	    for ch in s.chars() {
512	        match ch {
513	            '%' => out.push_str("%25"),
514	            '\r' => out.push_str("%0D"),
515	            '\n' => out.push_str("%0A"),
516	            other => out.push(other),
517	        }
518	    }
519	    out
520	}
521	
522	/// Encode a GitHub workflow command property value: the data encoding plus `:` and `,`, which delimit properties.
523	fn escape_annotation_property(s: &str) -> String {
524	    let mut out = String::with_capacity(s.len() + 8);
525	    for ch in s.chars() {
526	        match ch {
527	            '%' => out.push_str("%25"),
528	            '\r' => out.push_str("%0D"),
529	            '\n' => out.push_str("%0A"),
530	            ':' => out.push_str("%3A"),
531	            ',' => out.push_str("%2C"),
532	            other => out.push(other),
533	        }
534	    }
535	    out
536	}
