538	/// The fields every rendered error document starts with: `error: <code>`, `message: …`, `causes[N]: …` (only when
539	/// there are causes), `exit_code: 1`.
540	fn push_error_fields(out: &mut String, code: &str, message: &str, causes: &[String]) {
541	    out.push_str("error: ");
542	    out.push_str(code);
543	    out.push_str("\nmessage: ");
544	    out.push_str(&crate::toon::escape_value(message));
545	    crate::hints::append_inline_strings(out, "causes", causes.iter().map(String::as_str));
546	    out.push_str("\nexit_code: 1");
547	}
