549	#[cfg(feature = "miette")]
550	#[cfg_attr(docsrs, doc(cfg(feature = "miette")))]
551	impl miette::Diagnostic for DomainError {
552	    fn code<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
553	        Some(Box::new(self.code.label()))
554	    }
555	
556	    /// The hints, one per line, then one `caused by: …` line per cause; `None` when there are neither.
557	    ///
558	    /// miette prints a `source()` chain itself, but [`DomainError`] stores its causes as text, so they go here,
559	    /// labelled and after the guidance.
560	    fn help<'a>(&'a self) -> Option<Box<dyn std::fmt::Display + 'a>> {
561	        if self.hints.is_empty() && self.causes.is_empty() {
562	            return None;
563	        }
564	        let lines: Vec<String> = self
565	            .hints
566	            .iter()
567	            .map(|h| h.as_str().to_string())
568	            .chain(self.causes.iter().map(|c| format!("caused by: {c}")))
569	            .collect();
570	        Some(Box::new(lines.join("\n")))
571	    }
572	}
