574	/// The unified error type for michi-core.
575	#[derive(Debug, thiserror::Error)]
576	#[non_exhaustive]
577	pub enum Error {
578	    /// Invalid or malformed input.
579	    #[error("Invalid input: {0}")]
580	    InvalidInput(String),
581	
582	    /// A required resource was not found.
583	    #[error("Not found: {0}")]
584	    NotFound(String),
585	
586	    /// A classified domain error with hints, recovery, and retry metadata.
587	    #[error("{}: {}", .0.code.label(), .0.message)]
588	    Domain(#[from] DomainError),
589	}
590	
591	impl Error {
592	    /// Render this error as a TOON 4.4 document in the shape of [`DomainError::render`]: `Domain` renders its inner
593	    /// error; `InvalidInput(m)` and `NotFound(m)` render `error: invalid_input` / `error: not_found`, `message: m`
594	    /// (quoted per §7.2) and `exit_code: 1`, with no trailing newline.
595	    #[must_use]
596	    pub fn render(&self) -> String {
597	        let (code, message) = match self {
598	            Self::Domain(d) => return d.render(),
599	            Self::InvalidInput(m) => (ErrorCode::InvalidInput.label(), m),
600	            Self::NotFound(m) => (ErrorCode::NotFound.label(), m),
601	        };
602	        let mut out = String::with_capacity(48 + message.len());
603	        push_error_fields(&mut out, code, message, &[]);
604	        out
605	    }
606	
607	    /// The process exit code to use when this error is fatal.
608	    #[must_use]
609	    pub fn exit_code(&self) -> i32 {
610	        1
611	    }
612	
613	    /// Classify this error for routing decisions.
614	    #[must_use]
615	    pub fn class(&self) -> ErrorClass {
616	        match self {
617	            Self::Domain(d) if d.retryable => ErrorClass::Transient,
618	            Self::Domain(d) => d.code.default_class(),
619	            Self::InvalidInput(_) | Self::NotFound(_) => ErrorClass::User,
620	        }
621	    }
622	
623	    /// Whether this error is [`ErrorClass::Transient`]: calling again is expected to help without repeating an
624	    /// effect. A `Timeout` or `ExternalFailure` is retryable only when its `DomainError` was marked so.
625	    #[must_use]
626	    pub fn is_retryable(&self) -> bool {
627	        matches!(self.class(), ErrorClass::Transient)
628	    }
629	}
