16	/// Configuration for automatic retry behaviour.
17	#[derive(Debug, Clone, PartialEq)]
18	#[non_exhaustive]
19	pub struct RetryConfig {
20	    /// Maximum number of retry attempts (not counting the initial attempt).
21	    pub max_retries: u32,
22	    /// Base delay for exponential back-off.
23	    pub base_delay: Duration,
24	    /// Maximum delay cap — back-off never exceeds this.
25	    pub max_delay: Duration,
26	    /// Jitter factor in `[0.0, 1.0]`. `0.0` = no jitter, `1.0` = full jitter.
27	    pub jitter_factor: f64,
28	}
29	
30	/// Error returned by [`RetryConfig::try_new()`] when parameters are out of range.
31	///
32	/// `#[non_exhaustive]`: new checks may be added in a minor release.
33	#[derive(Debug, Clone, PartialEq)]
34	#[non_exhaustive]
35	pub enum RetryConfigError {
36	    /// `max_delay` must be non-zero (zero silently drops server `retry_after` hints).
37	    MaxDelayIsZero,
38	    /// `base_delay` must not exceed `max_delay`.
39	    BaseDelayExceedsMaxDelay {
40	        /// The provided `base_delay`.
41	        base: std::time::Duration,
42	        /// The provided `max_delay`.
43	        max: std::time::Duration,
44	    },
45	    /// `jitter_factor` must be in `[0.0, 1.0]`.
46	    JitterFactorOutOfRange {
47	        /// The provided `jitter_factor`.
48	        factor: f64,
49	    },
50	}
51	
52	impl std::fmt::Display for RetryConfigError {
53	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
54	        match self {
55	            Self::MaxDelayIsZero => f.write_str("max_delay must be non-zero"),
56	            Self::BaseDelayExceedsMaxDelay { base, max } => {
57	                write!(f, "base_delay ({base:?}) must not exceed max_delay ({max:?})")
58	            }
59	            Self::JitterFactorOutOfRange { factor } => write!(f, "jitter_factor {factor} is outside [0.0, 1.0]"),
60	        }
61	    }
62	}
63	
64	impl std::error::Error for RetryConfigError {}
65	
66	impl RetryConfig {
67	    /// Normalizing constructor — clamps all inputs to valid ranges silently.
68	    ///
69	    /// - `jitter_factor` → clamped to `[0.0, 1.0]`
70	    /// - `base_delay` → clamped to `min(base_delay, max_delay)`
71	    /// - `max_delay` → floored to `1ms` (prevents silent `retry_after` discard
72	    ///   when the caller passes zero)
73	    ///
74	    /// For NAPI-boundary callers (untrusted inputs), or wherever clamping is
75	    /// acceptable. Use [`RetryConfig::try_new()`] when you need explicit errors.
76	    #[must_use]
77	    pub fn new(
78	        max_retries: u32,
79	        base_delay: std::time::Duration,
80	        max_delay: std::time::Duration,
81	        jitter_factor: f64,
82	    ) -> Self {
83	        let max_delay = max_delay.max(std::time::Duration::from_millis(1));
84	        let base_delay = base_delay.min(max_delay);
85	        let jitter_factor = if jitter_factor.is_finite() { jitter_factor.clamp(0.0, 1.0) } else { 0.0 };
86	        Self { max_retries, base_delay, max_delay, jitter_factor }
87	    }
88	
89	    /// Strict constructor — returns `Err` if any parameter is out of range.
90	    ///
91	    /// For NAPI-boundary callers, use the normalizing [`RetryConfig::new()`] instead.
92	    ///
93	    /// # Errors
94	    ///
95	    /// [`RetryConfigError::MaxDelayIsZero`] when `max_delay` is zero, [`RetryConfigError::BaseDelayExceedsMaxDelay`]
96	    /// when `base_delay > max_delay`, and [`RetryConfigError::JitterFactorOutOfRange`] when `jitter_factor` is outside
97	    /// `[0.0, 1.0]` (or NaN).
98	    pub fn try_new(
99	        max_retries: u32,
100	        base_delay: std::time::Duration,
101	        max_delay: std::time::Duration,
102	        jitter_factor: f64,
103	    ) -> Result<Self, RetryConfigError> {
104	        if max_delay.is_zero() {
105	            return Err(RetryConfigError::MaxDelayIsZero);
106	        }
107	        if base_delay > max_delay {
108	            return Err(RetryConfigError::BaseDelayExceedsMaxDelay { base: base_delay, max: max_delay });
109	        }
110	        if !(0.0..=1.0).contains(&jitter_factor) {
111	            return Err(RetryConfigError::JitterFactorOutOfRange { factor: jitter_factor });
112	        }
113	        Ok(Self { max_retries, base_delay, max_delay, jitter_factor })
114	    }
115	}
116	
117	impl Default for RetryConfig {
118	    fn default() -> Self {
119	        Self {
120	            max_retries: 3,
121	            base_delay: Duration::from_millis(500),
122	            max_delay: Duration::from_secs(30),
123	            jitter_factor: 0.2,
124	        }
125	    }
126	}
