128	/// Compute the delay before the next retry attempt.
129	///
130	/// Returns `None` once `attempt >= max_retries`. Otherwise the delay is `base_delay * 2^attempt` plus jitter, raised to
131	/// `retry_after` when that is larger, and capped at `max_delay`. `base_delay` and `retry_after` are rounded up to whole
132	/// milliseconds first, so a positive delay is never zero; the cap is the exact `max_delay`.
133	#[must_use]
134	#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss, clippy::cast_sign_loss)]
135	pub fn next_retry_delay(
136	    config: &RetryConfig,
137	    attempt: u32,
138	    jitter_seed: f64,
139	    retry_after: Option<Duration>,
140	) -> Option<Duration> {
141	    if attempt >= config.max_retries {
142	        return None;
143	    }
144	    let jitter_seed = if jitter_seed.is_finite() { jitter_seed.clamp(0.0, 1.0) } else { 0.0 };
145	    let exp = 2u64.saturating_pow(attempt);
146	    let base_ms = ceil_millis(config.base_delay);
147	    let raw_ms = base_ms.saturating_mul(exp);
148	    let jitter_ms = (raw_ms as f64 * config.jitter_factor * jitter_seed) as u64;
149	    let jittered_ms = raw_ms.saturating_add(jitter_ms);
150	    let retry_after_ms = retry_after.map_or(0, ceil_millis);
151	    // Cap against the exact `max_delay`, so rounding up never exceeds it.
152	    Some(Duration::from_millis(jittered_ms.max(retry_after_ms)).min(config.max_delay))
153	}
154	
155	/// Whole milliseconds in `d`, rounded up so a positive delay never becomes zero and a server's `Retry-After` is never
156	/// shortened; saturates at `u64::MAX`.
157	fn ceil_millis(d: Duration) -> u64 {
158	    let ms = u64::try_from(d.as_millis()).unwrap_or(u64::MAX);
159	    if d.subsec_nanos().is_multiple_of(1_000_000) {
160	        ms
161	    } else {
162	        ms.saturating_add(1)
163	    }
164	}
