166	/// Parse the value of an HTTP `Retry-After` header (RFC 9110 §10.2.3) as a delay.
167	///
168	/// Accepts `delay-seconds` (ASCII digits only, no sign; a value past `u64::MAX` seconds saturates there) or an
169	/// HTTP-date in any of the three forms RFC 9110 §5.6.7 requires: IMF-fixdate, RFC 850 and asctime, with fixed-width
170	/// digit fields (`08:09:07`, not `8:9:7`). A date in the past, including one before 1970, is a zero delay. Surrounding
171	/// whitespace is ignored; anything else returns `None`.
172	#[must_use]
173	pub fn parse_retry_after(header_value: &str) -> Option<Duration> {
174	    parse_retry_after_at(header_value, std::time::SystemTime::now())
175	}
176	
177	/// Like [`parse_retry_after`], but takes the current time explicitly.
178	#[must_use]
179	pub fn parse_retry_after_at(header_value: &str, now: std::time::SystemTime) -> Option<Duration> {
180	    let trimmed = header_value.trim();
181	    // delay-seconds is 1*DIGIT (RFC 9110 §10.2.3); `u64::from_str` alone would also accept a leading `+`.
182	    if !trimmed.is_empty() && trimmed.bytes().all(|b| b.is_ascii_digit()) {
183	        // All digits, so the only parse failure is overflow.
184	        return Some(Duration::from_secs(trimmed.parse::<u64>().unwrap_or(u64::MAX)));
185	    }
186	    let target = parse_http_date(trimmed, now)?;
187	    let now_secs = match now.duration_since(std::time::UNIX_EPOCH) {
188	        Ok(d) => i64::try_from(d.as_secs()).unwrap_or(i64::MAX),
189	        Err(e) => i64::try_from(e.duration().as_secs()).map_or(i64::MIN, |s| -s),
190	    };
191	    // `target` is whole seconds; a fractional `now` only shortens the wait by less than a second, rounded down.
192	    let subsec = now.duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.subsec_nanos());
193	    let secs = target.saturating_sub(now_secs);
194	    if secs <= 0 {
195	        return Some(Duration::ZERO);
196	    }
197	    let whole = Duration::from_secs(u64::try_from(secs).unwrap_or(0));
198	    Some(whole.saturating_sub(Duration::from_nanos(u64::from(subsec))))
199	}
