201	/// `s` as a number when it is exactly `len` ASCII digits (no sign, no padding).
202	fn fixed_digits(s: &str, len: usize) -> Option<u64> {
203	    if s.len() != len || !s.bytes().all(|b| b.is_ascii_digit()) {
204	        return None;
205	    }
206	    s.parse().ok()
207	}
208	
209	/// Parse an HTTP-date in any of the three forms RFC 9110 §5.6.7 requires recipients to accept: IMF-fixdate
210	/// (`Sun, 06 Nov 1994 08:49:37 GMT`), the obsolete RFC 850 form (`Sunday, 06-Nov-94 08:49:37 GMT`) and the obsolete
211	/// asctime form (`Sun Nov  6 08:49:37 1994`), as seconds from the Unix epoch (negative before 1970). The weekday is
212	/// not checked against the date.
213	fn parse_http_date(s: &str, now: std::time::SystemTime) -> Option<i64> {
214	    parse_imf_fixdate(s).or_else(|| parse_rfc850_date(s, now)).or_else(|| parse_asctime_date(s))
215	}
216	
217	/// `IMF-fixdate = day-name "," SP date1 SP time-of-day SP GMT`, with `date1 = 2DIGIT SP month SP 4DIGIT`.
218	fn parse_imf_fixdate(s: &str) -> Option<i64> {
219	    let s = s.strip_suffix(" GMT")?;
220	    let (_weekday, rest) = s.split_once(", ")?;
221	    let mut parts = rest.split(' ');
222	    let day = fixed_digits(parts.next()?, 2)?;
223	    let month = month_number(parts.next()?)?;
224	    let year = i64::try_from(fixed_digits(parts.next()?, 4)?).ok()?;
225	    let time = parts.next()?;
226	    if parts.next().is_some() {
227	        return None;
228	    }
229	    to_system_time(year, month, day, time)
230	}
231	
232	/// `rfc850-date = day-name-l "," SP date2 SP time-of-day SP GMT`, with `date2 = day "-" month "-" 2DIGIT`.
233	///
234	/// A two-digit year means the latest year with those last two digits that is not more than 50 years after `now`'s
235	/// year (RFC 9110 §5.6.7): from 2026, `76` is 2076 and `77` is 1977.
236	fn parse_rfc850_date(s: &str, now: std::time::SystemTime) -> Option<i64> {
237	    let s = s.strip_suffix(" GMT")?;
238	    let (_weekday, rest) = s.split_once(", ")?;
239	    let (date, time) = rest.split_once(' ')?;
240	    let mut date_parts = date.split('-');
241	    let day = fixed_digits(date_parts.next()?, 2)?;
242	    let month = month_number(date_parts.next()?)?;
243	    let yy = i64::try_from(fixed_digits(date_parts.next()?, 2)?).ok()?;
244	    if date_parts.next().is_some() {
245	        return None;
246	    }
247	    // The latest year ending in `yy` that is at most 50 years after now's year.
248	    let limit = civil_year(now) + 50;
249	    let year = limit - (limit - yy).rem_euclid(100);
250	    to_system_time(year, month, day, time)
251	}
252	
253	/// `asctime-date = day-name SP month SP ( 2DIGIT / ( SP DIGIT ) ) SP time-of-day SP year`, with no zone (GMT).
254	fn parse_asctime_date(s: &str) -> Option<i64> {
255	    let mut parts = s.split_whitespace();
256	    let _weekday = parts.next()?;
257	    let month = month_number(parts.next()?)?;
258	    let day = parts.next()?;
259	    let day = fixed_digits(day, 2).or_else(|| fixed_digits(day, 1))?;
260	    let time = parts.next()?;
261	    let year = i64::try_from(fixed_digits(parts.next()?, 4)?).ok()?;
262	    if parts.next().is_some() {
263	        return None;
264	    }
265	    to_system_time(year, month, day, time)
266	}
267	
268	/// The UTC year `now` falls in (1970 for instants before the epoch, which no caller passes in practice).
269	fn civil_year(now: std::time::SystemTime) -> i64 {
270	    let secs = now.duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_secs());
271	    let days = i64::try_from(secs / 86_400).unwrap_or(i64::MAX / 2);
272	    // Inverse of `days_from_civil` (Howard Hinnant's civil_from_days), keeping only the year.
273	    let z = days + 719_468;
274	    let era = z.div_euclid(146_097);
275	    let doe = z.rem_euclid(146_097);
276	    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
277	    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
278	    let mp = (5 * doy + 2) / 153;
279	    let year = yoe + era * 400;
280	    if mp >= 10 {
281	        year + 1
282	    } else {
283	        year
284	    }
285	}
286	
287	/// Validate a civil date and `HH:MM:SS` time-of-day (GMT, two digits each) and convert them to seconds from the Unix
288	/// epoch, negative before 1970.
289	fn to_system_time(year: i64, month: u64, day: u64, time: &str) -> Option<i64> {
290	    if !(0..=9999).contains(&year) {
291	        return None;
292	    }
293	    let mut time_parts = time.split(':');
294	    let hour = fixed_digits(time_parts.next()?, 2)?;
295	    let minute = fixed_digits(time_parts.next()?, 2)?;
296	    let second = fixed_digits(time_parts.next()?, 2)?;
297	    let max_day = days_in_month(year, month)?;
298	    if time_parts.next().is_some() || hour > 23 || minute > 59 || second > 60 || day == 0 || day > max_day {
299	        return None;
300	    }
301	
302	    let days = days_from_civil(year, month, day);
303	    #[allow(clippy::cast_possible_wrap)]
304	    days.checked_mul(86_400)?.checked_add((hour * 3600 + minute * 60 + second) as i64)
305	}
306	
307	fn days_in_month(year: i64, month: u64) -> Option<u64> {
308	    Some(match month {
309	        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
310	        4 | 6 | 9 | 11 => 30,
311	        2 => {
312	            let is_leap = (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
313	            if is_leap {
314	                29
315	            } else {
316	                28
317	            }
318	        }
319	        _ => return None,
320	    })
321	}
322	
323	fn month_number(name: &str) -> Option<u64> {
324	    Some(match name {
325	        "Jan" => 1,
326	        "Feb" => 2,
327	        "Mar" => 3,
328	        "Apr" => 4,
329	        "May" => 5,
330	        "Jun" => 6,
331	        "Jul" => 7,
332	        "Aug" => 8,
333	        "Sep" => 9,
334	        "Oct" => 10,
335	        "Nov" => 11,
336	        "Dec" => 12,
337	        _ => return None,
338	    })
339	}
340	
341	#[allow(clippy::cast_possible_wrap, clippy::cast_possible_truncation, clippy::cast_sign_loss)]
342	fn days_from_civil(y: i64, m: u64, d: u64) -> i64 {
343	    let y = if m <= 2 { y - 1 } else { y };
344	    let era = if y >= 0 { y } else { y - 399 } / 400;
345	    let yoe = (y - era * 400) as u64;
346	    let mp = (m + 9) % 12;
347	    let doy = (153 * mp + 2) / 5 + d - 1;
348	    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
349	    era * 146_097 + doe as i64 - 719_468
350	}
351	
352	/// Return `true` if the HTTP status code is conventionally retryable (429, 502, 503, 504).
353	///
354	/// Only 429 and 503 say the request was not processed. After a 502 or 504 the upstream may have applied it (RFC 9110
355	/// §15.6), so retry those automatically only for an idempotent request (GET, PUT, DELETE, or one carrying an
356	/// idempotency key); otherwise check whether it took effect first.
357	#[must_use]
358	pub fn is_retryable_status(status: u16) -> bool {
359	    matches!(status, 429 | 502 | 503 | 504)
360	}
361	
362	/// An opaque idempotency key derived from operation inputs.
363	#[derive(Debug, Clone, PartialEq, Eq, Hash)]
364	pub struct IdempotencyKey(pub String);
365	
366	impl IdempotencyKey {
367	    /// Create an idempotency key from any string-like value.
368	    pub fn new(s: impl Into<String>) -> Self {
369	        Self(s.into())
370	    }
371	
372	    /// The raw key string.
373	    #[must_use]
374	    pub fn as_str(&self) -> &str {
375	        &self.0
376	    }
377	
378	    /// Construct a key from an operation name and raw input bytes, hashed with FNV-1a.
379	    #[must_use]
380	    pub fn from_hash(operation: &str, data: &[u8]) -> Self {
381	        Self(format!("{operation}:{:016x}", fnv1a_64(data)))
382	    }
383	}
384	
385	impl From<String> for IdempotencyKey {
386	    fn from(s: String) -> Self {
387	        Self(s)
388	    }
389	}
390	
391	impl From<&str> for IdempotencyKey {
392	    fn from(s: &str) -> Self {
393	        Self(s.into())
394	    }
395	}
396	
397	/// Result of an idempotency check.
398	///
399	/// # Caller responsibility
400	///
401	/// Use [`AlreadyDone`] when an operation fully completed in a prior call.
402	/// For operations that only partially completed (some steps succeeded, some
403	/// failed), use [`crate::idempotency::PartialSuccess`] instead. michi
404	/// does not enforce this distinction — the choice is the caller's responsibility.
405	#[derive(Debug, Clone, PartialEq)]
406	#[non_exhaustive]
407	pub enum AlreadyDone {
408	    /// The operation completed in a previous call.
409	    Yes {
410	        /// The previously stored result.
411	        result: String,
412	    },
413	    /// The operation has not been seen before — proceed with execution.
414	    No,
415	}
416	
417	/// Check whether an operation has already completed.
418	#[must_use]
419	pub fn already_done(stored: Option<String>) -> AlreadyDone {
420	    match stored {
421	        Some(result) => AlreadyDone::Yes { result },
422	        None => AlreadyDone::No,
423	    }
424	}
425	
426	/// Render an already-done response as a TOON 4.4 root object, with no trailing newline:
427	/// `operation: …`, `status: already_done`, `summary: …`, then the inline `help[N]: …` array when `hints` is non-empty.
428	/// `operation` and `summary` are quoted per §7.2.
429	#[must_use]
430	pub fn render_already_done(operation: &str, summary: &str, hints: &[String]) -> String {
431	    let mut out = String::with_capacity(64 + operation.len() + summary.len() + hints.len() * 50);
432	    out.push_str("operation: ");
433	    out.push_str(&crate::toon::escape_value(operation));
434	    out.push_str("\nstatus: already_done\nsummary: ");
435	    out.push_str(&crate::toon::escape_value(summary));
436	    crate::hints::append_help_block(&mut out, hints.iter().map(String::as_str));
437	    out
438	}
439	
440	fn fnv1a_64(data: &[u8]) -> u64 {
441	    const OFFSET_BASIS: u64 = 0xcbf2_9ce4_8422_2325;
442	    const PRIME: u64 = 0x0000_0100_0000_01b3;
443	    let mut hash = OFFSET_BASIS;
444	    for &byte in data {
445	        hash ^= u64::from(byte);
446	        hash = hash.wrapping_mul(PRIME);
447	    }
448	    hash
449	}
