1	//! MCP `CallToolResult` mapping — the shape a tool call returns to an MCP client.
2	
3	use crate::audience::Audience;
4	
5	/// One text content block. Wire-conformant with MCP's text content shape.
6	///
7	/// With the `serde` feature it serializes as `{"type":"text","text":…,"annotations":{"audience":[…]}}`. On input
8	/// `annotations` and `annotations.audience` are optional, as in MCP, and default to no audience; other annotation
9	/// fields (such as `priority`) are ignored. A `type` other than `"text"` is rejected.
10	#[derive(Debug, Clone, PartialEq)]
11	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
12	#[cfg_attr(feature = "serde", serde(into = "ContentBlockWire", from = "ContentBlockWire"))]
13	#[non_exhaustive]
14	pub struct ContentBlock {
15	    /// The block's text content.
16	    pub text: String,
17	    /// Which surface(s) this block is meant for.
18	    pub audience: Vec<Audience>,
19	}
20	
21	impl ContentBlock {
22	    /// Create a new ContentBlock.
23	    pub fn new(text: impl Into<String>, audience: Vec<Audience>) -> Self {
24	        Self { text: text.into(), audience }
25	    }
26	}
27	
28	#[cfg(feature = "serde")]
29	#[derive(Default, serde::Serialize, serde::Deserialize)]
30	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
31	#[cfg_attr(feature = "schemars", schemars(rename = "Annotations"))]
32	#[serde(rename_all = "camelCase")]
33	struct AnnotationsWire {
34	    #[serde(default)]
35	    audience: Vec<Audience>,
36	}
37	
38	#[cfg(feature = "serde")]
39	#[derive(serde::Serialize, serde::Deserialize)]
40	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
41	#[cfg_attr(feature = "schemars", schemars(rename = "ContentBlock"))]
42	struct ContentBlockWire {
43	    #[serde(rename = "type")]
44	    kind: TextKind,
45	    text: String,
46	    #[serde(default)]
47	    annotations: AnnotationsWire,
48	}
49	
50	/// The only content type `ContentBlock` models. Any other `type` (e.g. `"image"`) fails to deserialize instead of
51	/// silently becoming a text block.
52	#[cfg(feature = "serde")]
53	#[derive(serde::Serialize, serde::Deserialize)]
54	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
55	enum TextKind {
56	    #[serde(rename = "text")]
57	    Text,
58	}
59	
60	#[cfg(feature = "serde")]
61	impl From<ContentBlock> for ContentBlockWire {
62	    fn from(b: ContentBlock) -> Self {
63	        Self { kind: TextKind::Text, text: b.text, annotations: AnnotationsWire { audience: b.audience } }
64	    }
65	}
66	
67	#[cfg(feature = "serde")]
68	impl From<ContentBlockWire> for ContentBlock {
69	    fn from(w: ContentBlockWire) -> Self {
70	        Self { text: w.text, audience: w.annotations.audience }
71	    }
72	}
