74	/// The MCP `CallToolResult` shape: what a tool call returns to a client.
75	///
76	/// With the `serde` feature it serializes as `{"content":[…],"isError":…,"structuredContent":{…}}`, with
77	/// `structuredContent` the parsed JSON object and omitted when `structured_content` is empty. Serialization fails
78	/// when `structured_content` is neither empty nor the text of a JSON object, because MCP requires an object there.
79	/// On input only `content` is required: `isError` defaults to `false`, and an absent (or `null`)
80	/// `structuredContent` becomes the empty string; a `structuredContent` that is not an object is rejected.
81	#[derive(Debug, Clone, PartialEq)]
82	#[cfg_attr(feature = "serde", derive(serde::Deserialize))]
83	#[cfg_attr(feature = "serde", serde(from = "CallToolResultWire"))]
84	#[non_exhaustive]
85	pub struct CallToolResult {
86	    /// Text content blocks.
87	    pub content: Vec<ContentBlock>,
88	    /// Whether this is a tool execution error.
89	    pub is_error: bool,
90	    /// Machine-readable JSON companion to the text in `content`: the text of a JSON object, or empty for none. This is
91	    /// typically a richer, typed representation (e.g. `AgentResponse::render(OutputFormat::Json)`
92	    /// or `DomainError::render_json()`) — it is NOT a copy of `content[0].text`.
93	    pub structured_content: String,
94	}
95	
96	impl CallToolResult {
97	    /// Create a new CallToolResult.
98	    ///
99	    /// `structured_content` is not checked here: the caller is responsible for passing the text of a JSON object or
100	    /// the empty string. Anything else makes serialization fail. Use `CallToolResult::try_new` (`serde` feature) to
101	    /// check it up front.
102	    pub fn new(content: Vec<ContentBlock>, is_error: bool, structured_content: impl Into<String>) -> Self {
103	        Self { content, is_error, structured_content: structured_content.into() }
104	    }
105	
106	    /// Create a new CallToolResult, checking that `structured_content` is empty or the text of a JSON object.
107	    ///
108	    /// Caller opt-in — `new` does not call this; serialization performs the same check.
109	    ///
110	    /// # Errors
111	    ///
112	    /// [`StructuredContentError::InvalidJson`] when `structured_content` is not JSON, and
113	    /// [`StructuredContentError::NotAnObject`] when it is JSON but not an object.
114	    #[cfg(feature = "serde")]
115	    #[cfg_attr(docsrs, doc(cfg(feature = "serde")))]
116	    pub fn try_new(
117	        content: Vec<ContentBlock>,
118	        is_error: bool,
119	        structured_content: impl Into<String>,
120	    ) -> Result<Self, StructuredContentError> {
121	        let structured_content = structured_content.into();
122	        parse_structured_content(&structured_content)?;
123	        Ok(Self { content, is_error, structured_content })
124	    }
125	}
126	
127	/// The parsed `structuredContent` object, or `None` for the empty string.
128	#[cfg(feature = "serde")]
129	fn parse_structured_content(
130	    text: &str,
131	) -> Result<Option<serde_json::Map<String, serde_json::Value>>, StructuredContentError> {
132	    if text.is_empty() {
133	        return Ok(None);
134	    }
135	    match serde_json::from_str(text) {
136	        Ok(serde_json::Value::Object(map)) => Ok(Some(map)),
137	        Ok(other) => Err(StructuredContentError::NotAnObject {
138	            found: match other {
139	                serde_json::Value::Array(_) => "array",
140	                serde_json::Value::String(_) => "string",
141	                serde_json::Value::Number(_) => "number",
142	                serde_json::Value::Bool(_) => "boolean",
143	                serde_json::Value::Null | serde_json::Value::Object(_) => "null",
144	            },
145	        }),
146	        Err(e) => Err(StructuredContentError::InvalidJson { reason: e.to_string() }),
147	    }
148	}
149	
150	/// Error returned when `structured_content` is not empty and not the text of a JSON object, which MCP requires.
151	#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
152	#[non_exhaustive]
153	pub enum StructuredContentError {
154	    /// The text is not valid JSON.
155	    #[error("structuredContent is not valid JSON: {reason}")]
156	    InvalidJson {
157	        /// The JSON parser's message.
158	        reason: String,
159	    },
160	    /// The text is valid JSON but not an object.
161	    #[error("structuredContent must be a JSON object, got {found}")]
162	    NotAnObject {
163	        /// The JSON type found instead: `array`, `string`, `number`, `boolean` or `null`.
164	        found: &'static str,
165	    },
166	}
167	
168	#[cfg(feature = "serde")]
169	#[derive(serde::Serialize, serde::Deserialize)]
170	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
171	#[cfg_attr(feature = "schemars", schemars(rename = "CallToolResult"))]
172	#[serde(rename_all = "camelCase")]
173	struct CallToolResultWire {
174	    content: Vec<ContentBlock>,
175	    #[serde(default)]
176	    is_error: bool,
177	    #[serde(default, skip_serializing_if = "Option::is_none")]
178	    #[cfg_attr(feature = "schemars", schemars(schema_with = "object_schema"))]
179	    structured_content: Option<serde_json::Map<String, serde_json::Value>>,
180	}
181	
182	/// `structuredContent` is a JSON object (MCP); michi never emits `null` for it.
