5	/// One operation's identity within a batch: where it sat in the caller's op slice, what it was called, and (for
6	/// skipped operations) why it did not run.
7	///
8	/// `#[non_exhaustive]`: build it with [`OpRef::new`] (and [`OpRef::reason`]); the fields stay public.
9	#[derive(Debug, Clone, PartialEq, Eq)]
10	#[non_exhaustive]
11	pub struct OpRef {
12	    /// Position in the caller's op slice. `results[index]` answers `ops[index]`.
13	    pub index: usize,
14	    /// Display name for the operation.
15	    pub operation: String,
16	    /// A stable machine token such as `budget_exhausted`, `deadline` or `not_indexed`, never prose. michi does not
17	    /// define the vocabulary; the caller does. Rendered for skipped operations only; completed operations have no
18	    /// reason column.
19	    pub reason: Option<String>,
20	}
21	
22	impl OpRef {
23	    /// An operation at `index` with no reason.
24	    #[must_use]
25	    pub fn new(index: usize, operation: impl Into<String>) -> Self {
26	        Self { index, operation: operation.into(), reason: None }
27	    }
28	
29	    /// Attach the machine token saying why this operation was skipped.
30	    #[must_use]
31	    pub fn reason(mut self, reason: impl Into<String>) -> Self {
32	        self.reason = Some(reason.into());
33	        self
34	    }
35	}
36	
37	/// A single operation that failed within a larger multi-step operation.
38	///
39	/// `#[non_exhaustive]`: build it with [`FailedOp::new`] (and [`FailedOp::recovery`]); the fields stay public.
40	#[derive(Debug, Clone, PartialEq)]
41	#[non_exhaustive]
42	pub struct FailedOp {
43	    /// Position in the caller's op slice.
44	    pub index: usize,
45	    /// Identifier of the operation that failed.
46	    pub operation: String,
47	    /// Human-readable failure reason.
48	    pub reason: String,
49	    /// Optional structured recovery hint for this specific failure.
50	    pub recovery: Option<crate::recovery::RecoveryHint>,
51	}
52	
53	impl FailedOp {
54	    /// A failed operation at `index` with its reason and no recovery hint.
55	    #[must_use]
56	    pub fn new(index: usize, operation: impl Into<String>, reason: impl Into<String>) -> Self {
57	        Self { index, operation: operation.into(), reason: reason.into(), recovery: None }
58	    }
59	
60	    /// Attach a structured recovery hint for this failure.
61	    #[must_use]
62	    pub fn recovery(mut self, hint: crate::recovery::RecoveryHint) -> Self {
63	        self.recovery = Some(hint);
64	        self
65	    }
66	}
