68	/// Signals that an operation partially completed before a failure.
69	///
70	/// Use this when some steps of a multi-step operation succeeded: the agent can resume from the checkpoint rather
71	/// than retrying from scratch. Every entry carries its `index` in the caller's op slice, so the rendered report
72	/// keeps `results[i]` and `ops[i]` aligned.
73	///
74	/// For a fully-completed prior call, see [`crate::resilience::AlreadyDone`]
75	/// and [`crate::resilience::already_done`].
76	///
77	/// `#[non_exhaustive]`: build it with [`PartialSuccess::new`] or [`PartialSuccess::default`]; the fields stay
78	/// public.
79	#[derive(Debug, Clone, Default, PartialEq)]
80	#[non_exhaustive]
81	pub struct PartialSuccess {
82	    /// Steps that completed successfully.
83	    pub completed: Vec<OpRef>,
84	    /// Steps that failed, with reason and optional recovery hint.
85	    pub failed: Vec<FailedOp>,
86	    /// Steps that were not attempted, each optionally with the reason it was skipped.
87	    pub skipped: Vec<OpRef>,
88	}
89	
90	impl PartialSuccess {
91	    /// A partial-success report from the completed steps, the failed operations and the skipped steps.
92	    #[must_use]
93	    pub fn new(completed: Vec<OpRef>, failed: Vec<FailedOp>, skipped: Vec<OpRef>) -> Self {
94	        Self { completed, failed, skipped }
95	    }
96	
97	    /// Render as a TOON 4.4 root object, with no trailing newline: a quoted summary, one tabular array per non-empty
98	    /// outcome category, then the failed operations' recovery hints as a `recovery[N]{tool,params,reason}:` table
99	    /// (see [`crate::recovery::render_recovery`]).
100	    ///
101	    /// Format:
102	    /// ```text
103	    /// partial_success: "2 completed, 1 failed, 1 skipped"
104	    /// completed[2]{index,operation}:
105	    ///   0,create_issue
106	    ///   1,add_label
107	    /// failed[1]{index,operation,reason}:
108	    ///   2,assign_user,User 'ghost' not found
109	    /// skipped[1]{index,operation,reason}:
110	    ///   3,notify_team,budget_exhausted
111	    /// recovery[1]{tool,params,reason}:
112	    ///   assign_user,"{\"user\":\"alice\"}",null
113	    /// ```
114	    ///
115	    /// Rows keep the order of the vectors, and `index` is written as given (never renumbered). Every string is quoted
116	    /// per §7.2; a skipped step with no reason renders `null` in the `reason` column. A completed step's `reason` is
117	    /// not rendered. Empty categories are omitted.
118	    #[must_use]
119	    pub fn render(&self) -> String {
120	        let mut out = String::with_capacity(
121	            64 + self.completed.iter().map(|s| s.operation.len() + 24).sum::<usize>()
122	                + self.failed.iter().map(|f| f.operation.len() + f.reason.len() + 80).sum::<usize>()
123	                + self
124	                    .skipped
125	                    .iter()
126	                    .map(|s| s.operation.len() + s.reason.as_ref().map_or(4, String::len) + 24)
127	                    .sum::<usize>(),
128	        );
129	        let _ = write!(
130	            out,
131	            "partial_success: \"{} completed, {} failed, {} skipped\"",
132	            self.completed.len(),
133	            self.failed.len(),
134	            self.skipped.len()
135	        );
136	
137	        if !self.completed.is_empty() {
138	            table::push_header(&mut out, "completed", self.completed.len(), ["index", "operation"]);
139	            for c in &self.completed {
140	                table::push_row(&mut out, &[Cell::count(c.index), Cell::Str(&c.operation)]);
141	            }
142	        }
143	
144	        if !self.failed.is_empty() {
145	            table::push_header(&mut out, "failed", self.failed.len(), ["index", "operation", "reason"]);
146	            for f in &self.failed {
147	                table::push_row(&mut out, &[Cell::count(f.index), Cell::Str(&f.operation), Cell::Str(&f.reason)]);
148	            }
149	        }
150	
151	        if !self.skipped.is_empty() {
152	            table::push_header(&mut out, "skipped", self.skipped.len(), ["index", "operation", "reason"]);
153	            for s in &self.skipped {
154	                let cells = [Cell::count(s.index), Cell::Str(&s.operation), Cell::opt_str(s.reason.as_deref())];
155	                table::push_row(&mut out, &cells);
156	            }
157	        }
158	
159	        let recovery_hints: Vec<crate::recovery::RecoveryHint> =
160	            self.failed.iter().filter_map(|f| f.recovery.clone()).collect();
161	        crate::recovery::append_recovery(&mut out, &recovery_hints);
162	
163	        out
164	    }
165	
166	    /// `0` when all operations completed or were skipped; `1` when any failed.
167	    #[must_use]
168	    pub fn exit_code(&self) -> i32 {
169	        i32::from(!self.failed.is_empty())
170	    }
171	}
