374	        assert!(out.ends_with(&format!("\n{recovery}")), "got: {out}");
375	        assert_eq!(out.matches("recovery[").count(), 1, "got: {out}");
376	        assert!(!out.contains("help["), "got: {out}");
377	    }
378	}
