1	use std::fmt::Write as _;
2	
3	/// Status of an individual pipeline step.
4	///
5	/// Each terminal status maps to one recovery action an agent can take; see "Status model" in
6	/// `docs/spec/08-pipeline-execution.md`.
7	/// Only [`StepStatus::Completed`] and [`StepStatus::CompletedEarlier`] count as success.
8	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
9	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
10	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
11	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
12	#[non_exhaustive]
13	pub enum StepStatus {
14	    /// Not started yet.
15	    Pending,
16	    /// In flight. A finished run never reports it; it appears in records persisted while a run was in progress.
17	    Running,
18	    /// Ran and succeeded in this run.
19	    Completed,
20	    /// Its effect was already in place, so it was not run: it succeeded earlier in the same run (carried over by
21	    /// resume), the caller verified it as applied, or its precheck found the effect already applied.
22	    CompletedEarlier,
23	    /// Failed definitively, or with an error that is safe to replay. Also covers a step that was never started
24	    /// because its deadline group's window had closed (michi-pipeline's `DeadlinePassed`).
25	    Failed,
26	    /// Ran, but whether it took effect is unknown. Verify before running it again.
27	    OutcomeUnknown(UnknownCause),
28	    /// Never took effect, for the given reason.
29	    Skipped(SkipReason),
30	    /// Never invoked, for the given reason.
31	    NotRun(NotRunReason),
32	    /// The step's own code panicked: a harness failure, distinct from an error the step returned.
33	    Panicked,
34	}
35	
36	/// Why a step was skipped.
37	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
38	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
39	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
40	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
41	#[non_exhaustive]
42	pub enum SkipReason {
43	    /// A prerequisite did not complete.
44	    PrerequisiteFailed,
45	    /// The run was cancelled before this step took effect.
46	    Cancelled,
47	}
48	
49	/// Why a step was never invoked.
50	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
51	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
52	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
53	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
54	#[non_exhaustive]
55	pub enum NotRunReason {
56	    /// Its circuit breaker was open.
57	    CircuitOpen,
58	    /// Its precheck could not tell whether its effect was already in place, so it was not run. Rendered
59	    /// `unverified`.
60	    Unverified,
61	    /// Its start could not be recorded durably, so it was not run. Rendered `start_not_recorded`.
62	    StartNotRecorded,
63	}
64	
65	/// Why a step's outcome is unknown.
66	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
67	#[cfg_attr(feature = "schemars", derive(schemars::JsonSchema))]
68	#[cfg_attr(feature = "serde", derive(serde::Serialize, serde::Deserialize))]
69	#[cfg_attr(feature = "serde", serde(rename_all = "snake_case"))]
70	#[non_exhaustive]
71	pub enum UnknownCause {
72	    /// An attempt timed out.
73	    Timeout,
74	    /// A gateway reported HTTP 502 or 504.
75	    Gateway,
76	    /// The run was cancelled while the step was in flight and the attempt was dropped.
77	    Cancelled,
78	    /// The step was in flight when the process running it stopped.
79	    Interrupted,
80	    /// The step failed with an error that does not say whether its effect landed (an HTTP 500, say). Rendered
81	    /// `step_failed`.
82	    StepFailed,
83	}
84	
85	impl StepStatus {
86	    /// The snake_case status label used in rendered output, without its reason.
87	    #[must_use]
88	    pub fn label(&self) -> &'static str {
89	        match self {
90	            Self::Pending => "pending",
91	            Self::Running => "running",
92	            Self::Completed => "completed",
93	            Self::CompletedEarlier => "completed_earlier",
94	            Self::Failed => "failed",
95	            Self::OutcomeUnknown(_) => "outcome_unknown",
96	            Self::Skipped(_) => "skipped",
97	            Self::NotRun(_) => "not_run",
98	            Self::Panicked => "panicked",
99	        }
100	    }
101	
102	    /// The snake_case reason label for statuses that carry one, `None` otherwise.
103	    #[must_use]
104	    pub fn reason(&self) -> Option<&'static str> {
105	        match self {
106	            Self::Skipped(SkipReason::PrerequisiteFailed) => Some("prerequisite_failed"),
107	            Self::Skipped(SkipReason::Cancelled) | Self::OutcomeUnknown(UnknownCause::Cancelled) => Some("cancelled"),
108	            Self::NotRun(NotRunReason::CircuitOpen) => Some("circuit_open"),
109	            Self::OutcomeUnknown(UnknownCause::Timeout) => Some("timeout"),
110	            Self::OutcomeUnknown(UnknownCause::Gateway) => Some("gateway"),
111	            Self::OutcomeUnknown(UnknownCause::Interrupted) => Some("interrupted"),
112	            Self::OutcomeUnknown(UnknownCause::StepFailed) => Some("step_failed"),
113	            Self::NotRun(NotRunReason::Unverified) => Some("unverified"),
114	            Self::NotRun(NotRunReason::StartNotRecorded) => Some("start_not_recorded"),
115	            Self::Pending
116	            | Self::Running
117	            | Self::Completed
118	            | Self::CompletedEarlier
119	            | Self::Failed
120	            | Self::Panicked => None,
121	        }
122	    }
123	
124	    /// Whether the step succeeded: [`StepStatus::Completed`] or [`StepStatus::CompletedEarlier`].
125	    #[must_use]
126	    pub fn is_success(&self) -> bool {
127	        matches!(self, Self::Completed | Self::CompletedEarlier)
128	    }
129	
130	    /// Every status with every reason, in declaration order. [`StepStatus::from_labels`] searches this list, so a
131	    /// label is parsed by the same table that [`label`](Self::label) and [`reason`](Self::reason) write; a unit test
132	    /// names every variant without a wildcard, so a new one fails to compile there until it is listed here.
133	    pub const ALL: [Self; 16] = [
134	        Self::Pending,
135	        Self::Running,
136	        Self::Completed,
137	        Self::CompletedEarlier,
138	        Self::Failed,
139	        Self::OutcomeUnknown(UnknownCause::Timeout),
140	        Self::OutcomeUnknown(UnknownCause::Gateway),
141	        Self::OutcomeUnknown(UnknownCause::Cancelled),
142	        Self::OutcomeUnknown(UnknownCause::Interrupted),
143	        Self::OutcomeUnknown(UnknownCause::StepFailed),
144	        Self::Skipped(SkipReason::PrerequisiteFailed),
145	        Self::Skipped(SkipReason::Cancelled),
146	        Self::NotRun(NotRunReason::CircuitOpen),
147	        Self::NotRun(NotRunReason::Unverified),
148	        Self::NotRun(NotRunReason::StartNotRecorded),
149	        Self::Panicked,
150	    ];
151	
152	    /// The status a [`label`](Self::label) and [`reason`](Self::reason) pair name: the inverse of those two methods.
153	    ///
154	    /// # Errors
155	    ///
156	    /// [`StepLabelError`] for an unknown status, a status that needs a reason and has none, an unknown reason, or a
157	    /// reason on a status that takes none.
158	    pub fn from_labels(status: &str, reason: Option<&str>) -> Result<Self, StepLabelError> {
159	        let mut known = false;
160	        for candidate in Self::ALL {
161	            if candidate.label() != status {
162	                continue;
163	            }
164	            known = true;
165	            if candidate.reason() == reason {
166	                return Ok(candidate);
167	            }
168	        }
169	        let own = || status.to_string();
170	        if !known {
171	            return Err(StepLabelError::UnknownStatus { status: own() });
172	        }
173	        // The status exists but this reason does not fit: it either needs one or must not have one.
174	        match reason {
175	            None => Err(StepLabelError::MissingReason { status: own() }),
176	            Some(r) if Self::reasons_of(status).next().is_none() => {
177	                Err(StepLabelError::UnexpectedReason { status: own(), reason: r.to_string() })
178	            }
179	            Some(r) => Err(StepLabelError::UnknownReason { status: own(), reason: r.to_string() }),
180	        }
181	    }
182	
183	    /// The reason labels `status` takes, in declaration order; none for a status without a reason.
184	    fn reasons_of(status: &str) -> impl Iterator<Item = &'static str> + '_ {
185	        Self::ALL.into_iter().filter(move |s| s.label() == status).filter_map(|s| s.reason())
186	    }
187	}
