189	/// Why [`StepStatus::from_labels`] rejected a status and reason pair.
190	#[derive(Debug, Clone, PartialEq, Eq)]
191	#[non_exhaustive]
192	pub enum StepLabelError {
193	    /// The status label names no status.
194	    UnknownStatus {
195	        /// The label that was given.
196	        status: String,
197	    },
198	    /// The status needs a reason and none was given.
199	    MissingReason {
200	        /// The status label.
201	        status: String,
202	    },
203	    /// The status takes no reason and one was given.
204	    UnexpectedReason {
205	        /// The status label.
206	        status: String,
207	        /// The reason that was given.
208	        reason: String,
209	    },
210	    /// The status takes a reason, but not this one.
211	    UnknownReason {
212	        /// The status label.
213	        status: String,
214	        /// The reason that was given.
215	        reason: String,
216	    },
217	}
218	
219	/// `a, b, c` for the labels in `labels`, or `a, b or c` when `last_or` is set.
220	fn join_labels(labels: impl Iterator<Item = &'static str>, last_or: bool) -> String {
221	    let labels: Vec<&str> = labels.collect();
222	    match (labels.split_last(), last_or) {
223	        (Some((last, rest)), true) if !rest.is_empty() => format!("{} or {last}", rest.join(", ")),
224	        _ => labels.join(", "),
225	    }
226	}
227	
228	impl std::fmt::Display for StepLabelError {
229	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
230	        match self {
231	            Self::UnknownStatus { status } => {
232	                // Each status once, in declaration order (a status with several reasons appears several times).
233	                let mut seen: Vec<&'static str> = Vec::new();
234	                for s in StepStatus::ALL {
235	                    if !seen.contains(&s.label()) {
236	                        seen.push(s.label());
237	                    }
238	                }
239	                write!(f, "unknown step status {status:?}: expected one of {}", seen.join(", "))
240	            }
241	            Self::MissingReason { status } => {
242	                let expected = join_labels(StepStatus::reasons_of(status), true);
243	                write!(f, "step status {status:?} needs a reason: {expected}")
244	            }
245	            Self::UnexpectedReason { status, reason } => {
246	                write!(f, "step status {status:?} takes no reason, got {reason:?}")
247	            }
248	            Self::UnknownReason { status, reason } => {
249	                let expected = join_labels(StepStatus::reasons_of(status), true);
250	                write!(f, "unknown reason {reason:?} for step status {status:?}: expected {expected}")
251	            }
252	        }
253	    }
254	}
