263	pub struct PipelineStep {
264	    /// Step identifier.
265	    ///
266	    /// michi does not validate uniqueness — callers are responsible for ensuring
267	    /// step IDs are distinct within a pipeline if they intend to reference steps
268	    /// by ID. Duplicate IDs render without error but produce ambiguous output.
269	    pub id: String,
270	    /// Human-readable name.
271	    pub name: String,
272	    /// Current status.
273	    pub status: StepStatus,
274	}
