276	impl PipelineStep {
277	    /// A step with its id, display name and status.
278	    #[must_use]
279	    pub fn new(id: impl Into<String>, name: impl Into<String>, status: StepStatus) -> Self {
280	        Self { id: id.into(), name: name.into(), status }
281	    }
282	}
