284	/// A pipeline run state.
285	///
286	/// `#[non_exhaustive]`: build it with [`Pipeline::new`] or [`Pipeline::default`]; the fields stay public.
287	#[derive(Debug, Clone, Default, PartialEq, Eq)]
288	#[non_exhaustive]
289	pub struct Pipeline {
290	    /// Pipeline identifier.
291	    pub id: String,
292	    /// All steps in declaration order.
293	    pub steps: Vec<PipelineStep>,
294	}
295	
296	impl Pipeline {
297	    /// A pipeline with its id and steps in declaration order.
298	    #[must_use]
299	    pub fn new(id: impl Into<String>, steps: Vec<PipelineStep>) -> Self {
300	        Self { id: id.into(), steps }
301	    }
302	
303	    /// Render the pipeline state as a TOON 4.4 document: `step[N]{id,name,status,reason}:` with one row per step, or
304	    /// `step: []` when there are no steps, with no trailing newline. `status` is [`StepStatus::label`] and `reason`
305	    /// is [`StepStatus::reason`] or `null`. `id` and `name` are quoted when TOON's string rules (§7.2) require it.
306	    #[must_use]
307	    pub fn render(&self) -> String {
308	        let n = self.steps.len();
309	        if n == 0 {
310	            return String::from("step: []");
311	        }
312	        let capacity = 40 + n * 48;
313	        let mut out = String::with_capacity(capacity);
314	
315	        out.push_str("step[");
316	        let _ = write!(out, "{n}");
317	        out.push_str("]{id,name,status,reason}:");
318	
319	        for step in &self.steps {
320	            out.push_str("\n  ");
321	            out.push_str(&crate::toon::escape_value(&step.id));
322	            out.push(',');
323	            out.push_str(&crate::toon::escape_value(&step.name));
324	            out.push(',');
325	            out.push_str(step.status.label());
326	            out.push(',');
327	            out.push_str(step.status.reason().unwrap_or("null"));
328	        }
329	
330	        out
331	    }
332	}
