1	//! Renders of how an operation went: `renderDomainError`, `renderAlreadyDone`, `alreadyDone`,
2	//! `renderPartialSuccess` and `renderPipeline`.
3	
4	use napi::bindgen_prelude::Unknown;
5	use napi_derive::napi;
6	
7	use super::hints::JsRecoveryHint;
8	use super::input::{self, Budget, List, MAX_HINTS, MAX_NAME_BYTES, MAX_STEPS, MAX_STRING_BYTES};
9	use super::num::JsCount;
10	
11	/// Render the TOON 4.4 `already_done` document: `operation`, `status: already_done`, `summary`, `help`.
12	///
13	/// # Errors
14	///
15	/// Rejects more than 10,000 hints, an `operation` over 4 KiB, a `summary` or hint over 1 MiB, and more than 16 MiB
16	/// of strings per call.
17	#[napi(
18	    catch_unwind,
19	    js_name = "renderAlreadyDone",
20	    ts_args_type = "operation: string, summary: string, hints: Array<string>"
21	)]
22	pub fn render_already_done(operation: Unknown<'_>, summary: Unknown<'_>, hints: Unknown<'_>) -> napi::Result<String> {
23	    let mut budget = Budget::new();
24	    let hints = List::new(hints, "hints")?;
25	    input::check_len("hints", hints.len(), MAX_HINTS)?;
26	    let operation = budget.string(operation, "operation", MAX_NAME_BYTES)?;
27	    let summary = budget.string(summary, "summary", MAX_STRING_BYTES)?;
28	    let hints = budget.strings(&hints, "hints", MAX_HINTS, "hint", MAX_STRING_BYTES)?;
29	    Ok(crate::resilience::render_already_done(&operation, &summary, &hints))
30	}
31	
32	/// Render a classified `DomainError` as a TOON 4.4 document (`error`, `message`, `causes`, `exit_code`, `help`), or
33	/// as a GitHub Actions annotation (`::error title={code}::{message}`, without hints or causes).
34	///
35	/// `causes` (optional) are why the error happened, outermost first, rendered as their own `causes[N]: …` key after the
36	/// message; `hints` are what to do next.
37	///
38	/// # Errors
39	///
40	/// Rejects an unknown `code`, more than 10,000 hints or causes, a `code` over 4 KiB, a `message`, hint or cause over
41	/// 1 MiB, and more than 16 MiB of strings per call.
42	#[napi(
43	    catch_unwind,
44	    js_name = "renderDomainError",
45	    ts_args_type = "code: 'invalid_input' | 'not_found' | 'unauthorized' | 'forbidden' | 'conflict' | 'rate_limited' | \
46	                    'unavailable' | 'timeout' | 'external_failure', message: string, hints: Array<string>, \
47	                    githubAnnotation?: boolean | undefined | null, causes?: Array<string> | undefined | null"
48	)]
49	pub fn render_domain_error(
50	    code: Unknown<'_>,
51	    message: Unknown<'_>,
52	    hints: Unknown<'_>,
53	    github_annotation: Option<bool>,
54	    causes: Option<Unknown<'_>>,
55	) -> napi::Result<String> {
56	    let mut budget = Budget::new();
57	    let hints = List::new(hints, "hints")?;
58	    input::check_len("hints", hints.len(), MAX_HINTS)?;
59	    let causes = List::optional(causes, "causes")?;
60	    if let Some(causes) = &causes {
61	        input::check_len("causes", causes.len(), MAX_HINTS)?;
62	    }
63	    let code = budget.string(code, "code", MAX_NAME_BYTES)?;
64	    let message = budget.string(message, "message", MAX_STRING_BYTES)?;
65	    let hints = budget.strings(&hints, "hints", MAX_HINTS, "hint", MAX_STRING_BYTES)?;
66	    let causes = match &causes {
67	        Some(causes) => budget.strings(causes, "causes", MAX_HINTS, "cause", MAX_STRING_BYTES)?,
68	        None => Vec::new(),
69	    };
70	    domain_error(&code, message, hints, github_annotation.unwrap_or(false), causes)
71	}
72	
73	fn domain_error(
74	    code: &str,
75	    message: String,
76	    hints: Vec<String>,
77	    github_annotation: bool,
78	    causes: Vec<String>,
79	) -> napi::Result<String> {
80	    let code: crate::error::ErrorCode =
81	        code.parse().map_err(|e: crate::error::UnknownErrorCode| napi::Error::from_reason(e.to_string()))?;
82	    let mut err = crate::error::DomainError::new(code, message);
83	    err.causes = causes;
84	    for h in hints {
85	        err = err.hint(h);
86	    }
87	    Ok(if github_annotation { err.render_github_annotation() } else { err.render() })
88	}
