90	/// One failed operation for `renderPartialSuccess` (JavaScript-friendly).
91	#[napi(object, js_name = "FailedOp")]
92	#[derive(Debug, Clone)]
93	pub struct JsFailedOp {
94	    /// Position in the caller's op slice.
95	    #[napi(ts_type = "number")]
96	    pub index: JsCount,
97	    /// Identifier of the operation that failed.
98	    pub operation: String,
99	    /// Human-readable failure reason.
100	    pub reason: String,
101	    /// Optional recovery hint for this failure (no structured params over this boundary).
102	    #[napi(ts_type = "RecoveryHint | null")]
103	    pub recovery: Option<JsRecoveryHint>,
104	}
105	
106	/// One completed or skipped operation for `renderPartialSuccess` (JavaScript-friendly).
107	#[napi(object, js_name = "OpRef")]
108	#[derive(Debug, Clone)]
109	pub struct JsOpRef {
110	    /// Position in the caller's op slice. `results[index]` answers `ops[index]`.
111	    #[napi(ts_type = "number")]
112	    pub index: JsCount,
113	    /// Display name for the operation.
114	    pub operation: String,
115	    /// A stable machine token such as `budget_exhausted`, never prose. Rendered for skipped operations only.
116	    #[napi(ts_type = "string | null")]
117	    pub reason: Option<String>,
118	}
