120	/// Render a partial-success report: a quoted summary, then `completed[N]{index,operation}:`,
121	/// `failed[N]{index,operation,reason}:` and `skipped[N]{index,operation,reason}:` tables (empty categories omitted),
122	/// then the failed operations' recovery hints as one `recovery[N]{tool,params,reason}:` table. A skipped operation
123	/// without a `reason` renders `null` there.
124	///
125	/// # Errors
126	///
127	/// Rejects more than 10,000 entries in `completed`, `failed` or `skipped`, an `operation`, an `OpRef` `reason` or a
128	/// recovery `tool` over 4 KiB, a failed `reason` over 1 MiB, an `index` that is not an integer in `0..=2^53-1`, and
129	/// more than 16 MiB of strings per call.
130	#[napi(
131	    catch_unwind,
132	    js_name = "renderPartialSuccess",
133	    ts_args_type = "completed: Array<OpRef>, failed: Array<FailedOp>, skipped: Array<OpRef>"
134	)]
135	pub fn render_partial_success(
136	    completed: Unknown<'_>,
137	    failed: Unknown<'_>,
138	    skipped: Unknown<'_>,
139	) -> napi::Result<String> {
140	    let mut budget = Budget::new();
141	    let completed = List::new(completed, "completed")?;
142	    let failed = List::new(failed, "failed")?;
143	    let skipped = List::new(skipped, "skipped")?;
144	    input::check_len("completed", completed.len(), MAX_STEPS)?;
145	    input::check_len("failed", failed.len(), MAX_STEPS)?;
146	    input::check_len("skipped", skipped.len(), MAX_STEPS)?;
147	    let completed = budget.op_refs(&completed, "completed", MAX_STEPS)?;
148	    let failed = budget.failed_ops(&failed, MAX_STEPS)?;
149	    let skipped = budget.op_refs(&skipped, "skipped", MAX_STEPS)?;
150	    Ok(partial_success(completed, failed, skipped))
151	}
152	
153	fn partial_success(completed: Vec<JsOpRef>, failed: Vec<JsFailedOp>, skipped: Vec<JsOpRef>) -> String {
154	    let failed = failed
155	        .into_iter()
156	        .map(|f| {
157	            let op = crate::idempotency::FailedOp::new(f.index.get(), f.operation, f.reason);
158	            match f.recovery {
159	                Some(h) => op.recovery(h.into()),
160	                None => op,
161	            }
162	        })
163	        .collect();
164	    let op_refs = |ops: Vec<JsOpRef>| -> Vec<crate::idempotency::OpRef> {
165	        ops.into_iter()
166	            .map(|o| {
167	                let op = crate::idempotency::OpRef::new(o.index.get(), o.operation);
168	                match o.reason {
169	                    Some(r) => op.reason(r),
170	                    None => op,
171	                }
172	            })
173	            .collect()
174	    };
175	    crate::idempotency::PartialSuccess::new(op_refs(completed), failed, op_refs(skipped)).render()
176	}
