237	/// Classify an idempotency lookup: a stored result (any string, even empty) means the operation already completed;
238	/// `null` or `undefined` means it has not been seen.
239	///
240	/// # Errors
241	///
242	/// Rejects a `stored` value that is not a string, `null` or `undefined`, and one over 16 MiB.
243	#[napi(
244	    catch_unwind,
245	    js_name = "alreadyDone",
246	    ts_args_type = "stored?: string | undefined | null",
247	    ts_return_type = "AlreadyDone"
