249	pub fn already_done(stored: Option<Unknown<'_>>) -> napi::Result<JsAlreadyDone> {
250	    let mut budget = Budget::new();
251	    let stored = match stored {
252	        Some(v) if !input::is_nullish(v)? => Some(budget.string(v, "stored", input::MAX_INPUT_BYTES)?),
253	        _ => None,
254	    };
255	    Ok(done_or_not(stored))
