258	fn done_or_not(stored: Option<String>) -> JsAlreadyDone {
259	    // Every variant is named: a new one must fail to compile here rather than read as "not done" and re-run work.
260	    match crate::resilience::already_done(stored) {
261	        crate::resilience::AlreadyDone::Yes { result } => JsAlreadyDone { done: true, result: Some(result) },
262	        crate::resilience::AlreadyDone::No => JsAlreadyDone { done: false, result: None },
263	    }
264	}
