    #[test]
    fn render_already_done_basic() {
        let out = crate::resilience::render_already_done("delete_item", "already deleted", &[]);
        assert!(out.contains("operation: delete_item"), "got: {out}");
        assert!(out.contains("status: already_done"), "got: {out}");
