import sys

root = sys.argv[1]


def edit(path, pairs):
    p = root + '/' + path
    s = open(p).read()
    for old, new in pairs:
        if old not in s:
            raise SystemExit(f"{path}: missing {old[:90]!r}")
        s = s.replace(old, new, 1)
    open(p, 'w').write(s)


