#[test]
fn michi_writers_produce_checked_objects() {
    let err = crate::DomainError::new(crate::ErrorCode::Timeout, "a \"q\"\n")
        .hint("h")
        .recovery(crate::RecoveryHint::new("t").param("k", crate::KvValue::Float(1.5)));
    let resp = crate::AgentResponse::new("t").hint("h").recovery_hint(crate::RecoveryHint::new("r"));
    for result in [err.to_call_tool_result(), resp.to_call_tool_result(), resp.as_error().to_call_tool_result()] {
        let text = result.structured_content.expect("set").into_string();
        assert!(JsonObject::new(text.as_str()).is_ok(), "{text}");
/// `JSON.parse()` it themselves.
///
/// # Errors
///
/// Returns an error only if an internal invariant is violated (should not happen in normal use).
#[napi(catch_unwind)]
pub fn to_call_tool_result(&self) -> napi::Result<JsCallToolResult> {
    let result = self.built()?.to_call_tool_result();
    let structured_content = serde_json::from_str(&result.structured_content)
        .map_err(|e| napi::Error::from_reason(format!("structured_content was not valid JSON: {e}")))?;
    Ok(JsCallToolResult {
        content: result
            .content
            .into_iter()
            .map(|c| JsContentBlock {
                content_type: "text".to_string(),
                text: c.text,
                annotations: JsAnnotations {
                    audience: c
                        .audience
                        .into_iter()
                        .map(|a| match a {
                            crate::audience::Audience::Assistant => "assistant".to_string(),
                            crate::audience::Audience::User => "user".to_string(),
                        })
                        .collect(),
                },
            })
            .collect(),
        is_error: result.is_error,
        structured_content,
    })
}

