//! Probes for the audit's field-bypass examples. Written against the public-field API to show the bug; they stop
//! compiling once the fields are private.

use std::time::Duration;

use michi_core::{next_retry_delay, DomainError, ErrorCode, RetryConfig, MAY_HAVE_TAKEN_EFFECT_HINT};

#[test]
fn probe_zero_max_delay_after_try_new_keeps_retry_after() {
    let mut cfg = RetryConfig::try_new(3, Duration::from_millis(100), Duration::from_secs(120), 0.0).expect("valid");
    cfg.max_delay = Duration::ZERO;
    let delay = next_retry_delay(&cfg, 0, 0.5, Some(Duration::from_secs(60))).expect("attempt 0");
    assert!(delay >= Duration::from_secs(60), "hot retry: {delay:?} against Retry-After: 60s");
}

#[test]
fn probe_retryable_field_write_keeps_the_effect_hint_in_sync() {
    let mut e = DomainError::new(ErrorCode::Timeout, "POST /charge timed out");
    e.retryable = true;
    let has_hint = e.hints.iter().any(|h| h.as_str() == MAY_HAVE_TAKEN_EFFECT_HINT);
    assert!(!has_hint, "retryable:true must not also say verify first");
}

#[test]
fn probe_code_field_write_keeps_the_effect_hint_in_sync() {
    let mut e = DomainError::new(ErrorCode::RateLimited, "slow down");
    e.code = ErrorCode::Timeout;
    let has_hint = e.hints.iter().any(|h| h.as_str() == MAY_HAVE_TAKEN_EFFECT_HINT);
    assert!(!e.retryable || has_hint, "a retryable timeout with no verify-first hint is the unsafe retry");
}

