3: use std::fmt;
4: 
5: /// Longest accepted id, in bytes (ids are ASCII, so also in characters).
6: pub const MAX_ID_LEN: usize = 64;
7: 
8: /// Why a string is not a valid [`StepId`] or [`RunId`].
9: #[non_exhaustive]
10: #[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
11: pub enum IdError {
12:     /// The id is empty.
13:     #[error("id must not be empty")]
14:     Empty,
15:     /// The id is longer than [`MAX_ID_LEN`].
16:     #[error("id is {len} bytes long, the maximum is {max}")]
17:     TooLong {
18:         /// The id's length in bytes.
19:         len: usize,
20:         /// The maximum length.
21:         max: usize,
22:     },
23:     /// The id contains a character outside the slug charset.
24:     #[error("id has {ch:?} at byte {index}; use ASCII letters, digits, '_', '-' or '.', starting with a letter, digit or '_'")]
25:     InvalidChar {
26:         /// The offending character.
27:         ch: char,
28:         /// Its byte offset.
29:         index: usize,
30:     },
31: }
32: 
33: /// Checks the slug rule shared by [`StepId`] and [`RunId`].
34: fn validate(s: &str) -> Result<(), IdError> {
35:     if s.is_empty() {
36:         return Err(IdError::Empty);
37:     }
38:     if s.len() > MAX_ID_LEN {
39:         return Err(IdError::TooLong { len: s.len(), max: MAX_ID_LEN });
40:     }
41:     for (index, ch) in s.char_indices() {
42:         let ok = ch.is_ascii_alphanumeric() || ch == '_' || (index > 0 && (ch == '-' || ch == '.'));
43:         if !ok {
44:             return Err(IdError::InvalidChar { ch, index });
45:         }
46:     }
47:     Ok(())
48: }
