118: slug_id! {
119:     /// One run's identity, supplied by the caller. Resume reuses it, so a step's idempotency key
120:     /// (`run_id:step_id`) stays the same across attempts and across resume. Reusing a run id for a different plan or
121:     /// different inputs makes downstream deduplication treat new work as a repeat; michi cannot detect that.
122:     RunId
123: }
124: 
125: impl RunId {
126:     /// Builds a run id that is unique in practice without a UUID dependency:
127:     /// `{prefix}-{millis}-{pid}-{counter}-{random}`, the numbers in base 36. `random` is 64 bits from the standard
128:     /// library's per-process randomly keyed hasher, mixed with the other parts, so two hosts that start in the same
129:     /// millisecond with the same pid and counter (containers all run as pid 1) still get different ids. The run id is
130:     /// the prefix of every step's idempotency key, so a collision would let a downstream that deduplicates treat new
131:     /// work as a repeat of old.
132:     ///
133:     /// This is unique with overwhelming probability, not by construction: if you need a global guarantee (a
134:     /// deduplicating downstream that outlives you), supply your own UUID or other id from a source you trust with
135:     /// [`RunId::try_new`]. The random part takes 14 of the [`MAX_ID_LEN`] bytes, so keep the prefix short (about 30
136:     /// bytes at most).
137:     ///
138:     /// # Errors
139:     ///
140:     /// An [`IdError`] if `prefix` is not a valid slug or the result would exceed [`MAX_ID_LEN`].
141:     pub fn unique(prefix: &str) -> Result<Self, IdError> {
142:         use std::hash::BuildHasher;
143: 
144:         static COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
145:         validate(prefix)?;
146:         let millis = std::time::SystemTime::now()
147:             .duration_since(std::time::UNIX_EPOCH)
148:             .map_or(0, |d| u64::try_from(d.as_millis()).unwrap_or(u64::MAX));
149:         let pid = u64::from(std::process::id());
150:         let seq = COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
151:         // `RandomState` is keyed from the OS's randomness once per process (and stepped per instance), so the hash is
152:         // unpredictable across processes even when millis, pid and seq match.
153:         let entropy = std::collections::hash_map::RandomState::new().hash_one((millis, pid, seq));
154:         Self::try_new(unique_id(prefix, millis, pid, seq, entropy))
155:     }
156: }
157: 
158: /// `{prefix}-{millis}-{pid}-{seq}-{entropy}` in base 36. Every number has its own separator: base-36 numbers vary in
159: /// length, so without one two different (pid, seq) pairs could print the same digits.
160: fn unique_id(prefix: &str, millis: u64, pid: u64, seq: u64, entropy: u64) -> String {
161:     let mut id = String::with_capacity(prefix.len() + 4 + 4 * 13);
162:     id.push_str(prefix);
163:     for n in [millis, pid, seq, entropy] {
164:         id.push('-');
165:         push_base36(&mut id, n);
166:     }
167:     id
168: }
169: 
