        wire["isError"] = is_error.into();
    }
    let object: Option<serde_json::Map<String, serde_json::Value>> =
        r.structured.as_ref().map(|e| e.iter().map(|(k, v)| (k.clone(), v.clone().into())).collect());
    if let Some(object) = &object {
        wire["structuredContent"] = serde_json::Value::Object(object.clone());
    } else if r.structured_null {
        wire["structuredContent"] = serde_json::Value::Null;
    }
    // `extra_key` may collide with a real key; the accepted result is then not the one asserted below.
    if ["content", "isError", "structuredContent"].contains(&r.extra_key.as_str()) {
        return;
    }
    let parsed: CallToolResult =
        serde_json::from_value(wire.clone()).unwrap_or_else(|e| panic!("rejected {wire}: {e}"));
    assert_eq!(parsed.content.len(), 1);
    assert_eq!(parsed.content[0].text, r.text);
    assert_eq!(parsed.is_error, r.is_error.unwrap_or(false));
    let want_audience: Vec<Audience> =
        r.audience.iter().flatten().map(|&a| if a { Audience::Assistant } else { Audience::User }).collect();
    assert_eq!(parsed.content[0].audience, want_audience);
    match &object {
        Some(object) => {
            let back: serde_json::Value = serde_json::from_str(&parsed.structured_content).unwrap();
            assert_eq!(back, serde_json::Value::Object(object.clone()));
        }
        None => assert_eq!(parsed.structured_content, ""),
    }

    // And these are rejected: a non-text block, a non-object structuredContent.
    let mut bad = wire.clone();
    bad["content"][0]["type"] = "image".into();
    let mut link: Option<Box<Link>> = None;
    for text in input.chain.iter().take(300).rev() {
        link = Some(Box::new(Link { text: text.clone(), source: link }));
    }
    if let Some(head) = link {
        let e = DomainError::from_error_with_causes(ErrorCode::ExternalFailure, &*head);
        assert!(e.causes.len() <= 128);
        let _ = e.render();
        serde_json::from_str::<serde_json::Value>(&e.render_json()).expect("render_json is valid JSON");
    }

    // The pipeline conversion, with a planted token somewhere in the step text.
    let text = format!("{} {} {}", input.step_text, planted(input.shape), input.step_text);
    let err = match input.which % 6 {
        0 => ExecutionError::Http { status: input.status, message: text, retry_after: None },
        1 => ExecutionError::failed(text),
        2 => ExecutionError::Panicked { message: text },
        3 => ExecutionError::DeadlinePassed { message: text },
        4 => ExecutionError::StepFailed {
            step_id: "s".into(),
            step_name: "S".into(),
            source: Box::new(ExecutionError::failed(text)),
        },
        _ => ExecutionError::AmbiguousOutcome { source: Box::new(ExecutionError::failed(text)) },
    };
    let d: DomainError = err.into();
    assert!(d.message.len() < 200, "the trusted message stays fixed text: {}", d.message.len());
    for cause in &d.causes {
        assert!(cause.len() <= 512 + '…'.len_utf8(), "cause of {} bytes", cause.len());
    }
    assert!(!d.render().contains(PLANTED), "planted token survived: {}", d.render());
    assert!(!d.render_json().contains(PLANTED), "planted token survived in JSON");
    serde_json::from_str::<serde_json::Value>(&d.render_json()).expect("render_json is valid JSON");
});

